import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Interface: ScoreTrigger","description":"","frontmatter":{},"headers":[],"relativePath":"api/twine/interfaces/ScoreTrigger.md","filePath":"api/twine/interfaces/ScoreTrigger.md"}'),c={name:"api/twine/interfaces/ScoreTrigger.md"};function i(n,e,s,l,h,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<p><a href="./../">twine</a> / ScoreTrigger</p><h1 id="interface-scoretrigger" tabindex="-1">Interface: ScoreTrigger <a class="header-anchor" href="#interface-scoretrigger" aria-label="Permalink to &quot;Interface: ScoreTrigger&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/area.ts#L80" target="_blank" rel="noreferrer">area.ts:80</a></p><p>Activate an area from a scoreboard value. Give exactly one of <a href="#equals">equals</a> (a single value) or <a href="#matches">matches</a> (an inclusive band, either bound open).</p><p>By default a score trigger <strong>latches</strong>: it switches the area on and leaves it on until something calls <code>&lt;name&gt;/deactivate</code>. Set <code>latch: false</code> to have it track the score both ways, deactivating as soon as the score stops matching - the score-space equivalent of a player leaving a presence region.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="equals" tabindex="-1">equals? <a class="header-anchor" href="#equals" aria-label="Permalink to &quot;equals?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>equals?</strong>: <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/area.ts#L85" target="_blank" rel="noreferrer">area.ts:85</a></p><p>Activate while the score is exactly this. Mutually exclusive with <a href="#matches">matches</a>.</p><hr><h3 id="kind" tabindex="-1">kind <a class="header-anchor" href="#kind" aria-label="Permalink to &quot;kind&quot;">​</a></h3><blockquote><p><strong>kind</strong>: <code>&quot;score&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/area.ts#L81" target="_blank" rel="noreferrer">area.ts:81</a></p><hr><h3 id="latch" tabindex="-1">latch? <a class="header-anchor" href="#latch" aria-label="Permalink to &quot;latch?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>latch?</strong>: <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/area.ts#L89" target="_blank" rel="noreferrer">area.ts:89</a></p><p>Default <code>true</code>. <code>false</code> deactivates the area once the score stops matching.</p><hr><h3 id="matches" tabindex="-1">matches? <a class="header-anchor" href="#matches" aria-label="Permalink to &quot;matches?&quot;">​</a></h3><blockquote><p><code>optional</code> <strong>matches?</strong>: <code>object</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/area.ts#L87" target="_blank" rel="noreferrer">area.ts:87</a></p><p>Activate while the score is within this inclusive band; omit a bound to leave it open.</p><h4 id="max" tabindex="-1">max? <a class="header-anchor" href="#max" aria-label="Permalink to &quot;max?&quot;">​</a></h4><blockquote><p><code>optional</code> <strong>max?</strong>: <code>number</code></p></blockquote><h4 id="min" tabindex="-1">min? <a class="header-anchor" href="#min" aria-label="Permalink to &quot;min?&quot;">​</a></h4><blockquote><p><code>optional</code> <strong>min?</strong>: <code>number</code></p></blockquote><hr><h3 id="objective" tabindex="-1">objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;objective&quot;">​</a></h3><blockquote><p><strong>objective</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/area.ts#L82" target="_blank" rel="noreferrer">area.ts:82</a></p><hr><h3 id="target" tabindex="-1">target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;target&quot;">​</a></h3><blockquote><p><strong>target</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/1f7cf8c4b76144202afb9534cfbe54d591828868/twine/src/area.ts#L83" target="_blank" rel="noreferrer">area.ts:83</a></p>',36)])])}const f=a(c,[["render",i]]);export{p as __pageData,f as default};
